function validate([locations, start, finish, fuel]) {
  if (!Array.isArray(locations) || locations.length < 2 || locations.length > 100) return 'locations needs 2 to 100 cities.';
  if (locations.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each location is an integer from 1 to 10^9.';
  if (new Set(locations).size !== locations.length) return 'All locations must be distinct.';
  const n = locations.length;
  if (!Number.isInteger(start) || start < 0 || start >= n) return 'start must be a valid city index.';
  if (!Number.isInteger(finish) || finish < 0 || finish >= n) return 'finish must be a valid city index.';
  if (!Number.isInteger(fuel) || fuel < 1 || fuel > 200) return 'fuel is an integer from 1 to 200.';
  return null;
}

