function countRoutes(locations, start, finish, fuel) {
  const MOD = 1e9 + 7;
  const n = locations.length;
  const ways = Array.from({ length: fuel + 1 }, () => new Array(n).fill(0));

  for (let remaining = 0; remaining <= fuel; remaining++) {
    for (let city = 0; city < n; city++) {
      let count = city === finish ? 1 : 0;
      for (let next = 0; next < n; next++) {
        if (next === city) continue;
        const cost = Math.abs(locations[city] - locations[next]);
        if (cost <= remaining) {
          count = (count + ways[remaining - cost][next]) % MOD;
        }
      }
      ways[remaining][city] = count;
    }
  }
  return ways[fuel][start];
}

