function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 4);
  const span = size === 'large' ? [100, 400, 5000, 1e9][Math.floor(rand() * 4)] : n + Math.floor(rand() * 10);
  const base = size === 'large' && span < 1e9 ? Math.floor(rand() * (1e9 - span)) : 0;
  const used = new Set();
  while (used.size < n) used.add(base + 1 + Math.floor(rand() * span));
  const locations = [...used];
  const start = Math.floor(rand() * n);
  const finish = rand() < 0.2 ? start : Math.floor(rand() * n);
  const fuel = size === 'large' ? 200 - Math.floor(rand() * 20) : 1 + Math.floor(rand() * 8);
  return [locations, start, finish, fuel];
}
